ezCollections.Pets =
{
    [4055] = { 2671, 9, 2, nil, "El centro lógico de una ardilla mecánica le indica que recolecte y almacene tanto tuercas como tornillos para el invierno.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [10673] = { 7385, 7, 2, nil, "Donni Anthania planea que entierren a un bombay con ella cuando muera. Un aventurero sabio puede dar un uso mucho mejor a sus talentos.", 2, "|cFFFFD200Vendedor: |rDonni Anthania|n|cFFFFD200Zona: |rBosque de Elwynn|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10674] = { 7384, 7, 2, nil, "Donni Anthania invita a estos gatos a sus fiestas de té. Pero no sirve su bebida favorita: las lágrimas de sus enemigos.", 2, "|cFFFFD200Vendedor: |rDonni Anthania|n|cFFFFD200Zona: |rBosque de Elwynn|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10675] = { 7383, 7, 2, nil, "Viejo dicho de Alterac: 'Un gato tiene nueve vidas, pero solo necesita una'.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rMontañas de Alterac" },
    [10676] = { 7382, 7, 2, nil, "La última persona que intentó educar a este gato aprendió rápidamente que una alfombra sucia es mejor que tener todo lo demás destrozado.", 2, "|cFFFFD200Vendedor: |rDonni Anthania|n|cFFFFD200Zona: |rBosque de Elwynn|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10677] = { 7380, 7, 2, nil, "Conocido por sus ojos azules. También considerado un manjar por los múrlocs gigantes.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r60|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10678] = { 7381, 7, 2, nil, "Dormir es la segunda actividad favorita de este gato. La primera es bostezar.", 2, "|cFFFFD200Vendedor: |rDonni Anthania|n|cFFFFD200Zona: |rBosque de Elwynn|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10679] = { 7386, 7, 2, nil, "'La reina tuvo tres gatitos. El primero le regaló una jugosa rata. El segundo, una sabrosa liebre. Y el blanco, su favorito, le presentó la cabeza de su rival'.", 2, "|cFFFFD200Vendedor: |rTimmy el Pequeño|n|cFFFFD200Zona: |rCiudad de Ventormenta|n|cFFFFD200Coste: |r60|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10680] = { 7390, 2, 2, nil, "Hay quien dice que a este pájaro inteligente se le puede enseñar a hablar, pero es lo bastante listo como para mantener el pico cerrado.", 2, "|cFFFFD200Vendedor: |rNarkk|n|cFFFFD200Zona: |rVega de Tuercespina|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10682] = { 7391, 2, 2, nil, "Los trolls de la jungla entrenan a estas aves para imitar llamadas de auxilio con el fin de atraer a viajeros desprevenidos hacia sus trampas.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rVega de Tuercespina" },
    [10683] = { 7387, 2, 2, nil, "Mascota favorita de los piratas Defias, esta colorida ave es muy útil para recordar contraseñas, listas de la compra y recetas de galletas.", 0, "|cFFFFD200Botín: |rPirata Defias|n|cFFFFD200Zona: |rLas Minas de la Muerte" },
    [10684] = { 7389, 2, 2, nil, "Mascota favorita de los goblins de Bahía del Botín, esta colorida ave es famosa por su habilidad para contar monedas, cuadrar presupuestos y mentir sobre contratos.", 2, "|cFFFFD200Vendedor: |rNarkk|n|cFFFFD200Zona: |rVega de Tuercespina|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10685] = { 7394, 2, 2, nil, "También piensa que tú sabes a pollo.", 2, "|cFFFFD200Vendedor: |rMagus Tirth|n|cFFFFD200Zona: |rLas Mil Agujas|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10688] = { 7395, 4, 2, nil, "La cucaracha suele ser una compra impulsiva. A sus dueños les cuesta mucho desprenderse de ella incluso tras numerosos intentos.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendedor: |rJeremiah Payson|n|cFFFFD200Zona: |rEntrañas|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10695] = { 7543, 1, 2, nil, "Espera que algún día pueda crecer para destruir aldeas, igual que mamá.", 0, "|cFFFFD200Botín: |rCrías de dragón|n|cFFFFD200Zona: |rMarjal Revolcafango, Tierras Inhóspitas" },
    [10696] = { 7547, 1, 2, nil, "Al igual que otros miembros del Vuelo Azul, estas caprichosas criaturas muestran afinidad por la magia arcana.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rAzshara" },
    [10697] = { 7544, 1, 2, nil, "Procedente de Los Humedales, este joven dragón apenas está aprendiendo a cazar, escupir fuego y sembrar una adorable destrucción.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rLos Humedales" },
    [10698] = { 7545, 1, 2, nil, "Criada y alimentada antaño por el dragón verde Itharius, esta raza única de dragón se ha establecido en las junglas de Feralas.", 0, "|cFFFFD200Botín: |rCría adolescente, Cría soñadora|n|cFFFFD200Zona: |rPantano de las Penas" },
    [10703] = { 7550, 8, 2, nil, "Los vendedores de la Feria de la Luna Negra ofrecen maravillas extrañas y exóticas. También venden ranas de bosque.", 2, "|cFFFFD200Vendedor: |rFlik|n|cFFFFD200Evento: |rFeria de la Luna Negra|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10704] = { 7549, 8, 2, nil, "Conocidas por sus poderosas patas y su aguda vista.", 2, "|cFFFFD200Vendedor: |rFlik|n|cFFFFD200Evento: |rFeria de la Luna Negra|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10706] = { 7555, 2, 2, nil, "Esta ave rapaz de oscuro plumaje a menudo es vista como un presagio de fatalidad entre los druidas de Teldrassil.", 2, "|cFFFFD200Vendedor: |rShylenai|n|cFFFFD200Zona: |rDarnassus|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10707] = { 7553, 2, 2, nil, "A los niños elfos de la noche se les entrega una pluma de búho en su primer cumpleaños como símbolo de buena suerte.", 2, "|cFFFFD200Vendedor: |rShylenai|n|cFFFFD200Zona: |rDarnassus|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10708] = { 7554, 2, 26, nil, "Los fúrbolg de Cuna del Invierno aprecian las brillantes plumas blancas de estas majestuosas criaturas para propósitos rituales.", 11, "" },
    [10709] = { 14421, 4, 2, nil, "Un complejo sistema de madrigueras protege al perrito de la pradera de las enormes pezuñas de sus vecinos.", 2, "|cFFFFD200Vendedor: |rHalpa|n|cFFFFD200Zona: |rCima del Trueno|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10711] = { 7560, 4, 2, nil, "Si te pones a perseguir conejos de las nieves, sabes que vas a tropezar.", 2, "|cFFFFD200Vendedor: |rYarlyn Cuellobarba|n|cFFFFD200Zona: |rDun Morogh|n|cFFFFD200Coste: |r20|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10713] = { 7561, 7, 2, nil, "Compañero predilecto de los magos del Kirin Tor, este reptil hace que uno se pregunte si es realmente una serpiente o algo totalmente distinto.", 2, "|cFFFFD200Vendedor: |rBreanni|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [10714] = { 7565, 7, 2, nil, "Xan'tish rastrea, captura y entrena intrépidamente a estas nobles serpientes para que ayuden a sus camaradas en combate.", 2, "|cFFFFD200Vendedor: |rXan'tish|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10716] = { 7562, 7, 2, nil, "La serpiente marrón es nativa de los territorios controlados por la Horda. Parece insignificante hasta que sus víctimas están a tiro.", 2, "|cFFFFD200Vendedor: |rXan'tish|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [10717] = { 7567, 7, 2, nil, "La serpiente carmesí es la favorita de los trolls Lanza Negra no solo por su naturaleza feroz, sino también por su inquebrantable lealtad.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t|n|n|cFFFFD200Vendedor: |rXan'tish|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [12243] = { 8376, 9, 18, nil, "No hay de qué preocuparse; creo que los mecanismos de combate y la lógica de rastreo han sido desactivados en esta unidad. --Oglethorpe Obnoticus", 1, "|cFFFFD200Misión:|r Un OOX propio|n|cFFFFD200Zona:|r Bahía del Botín|n" },
    [13548] = { 30379, 2, 18, nil, "No llames gallina a este pájaro a menos que quieras acabar escaldado.", 1, "|cFFFFD200Misión: |r¡CLOQUEA!|n|cFFFFD200Zona: |rPáramos de Poniente" },
    [15048] = { 9656, 9, 2, nil, "Posiblemente explosivo, definitivamente adorable. Manténgase alejado de llamas abiertas.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [15049] = { 9657, 9, 2, nil, "Este diminuto robot de seguridad pacificadora suele estar equipado con los últimos neutralizadores arcanos y aporreadores de multitudes. No apto para ecologistas.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [15067] = { 9662, 1, 2, nil, "A estas adorables criaturas les encanta acurrucarse con sus dueños después de un largo día de brutal y sangrienta batalla.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rFeralas" },
    [15999] = { 10259, 7, 2050, nil, "Los huargos son los compañeros preferidos de los orcos y son ferozmente leales en el campo de batalla.", 1, "|cFFFFD200Misión: |rLas mascotas exóticas de Kibler|n|cFFFFD200Zona: |rCumbre de Roca Negra Inferior" },
    [16450] = { 10598, 7, 2, nil, "Aunque nacida en las cálidas alturas de Cumbre de Roca Negra, la cría humeante puede sobrevivir en la mayoría de entornos.", 1, "|cFFFFD200Misión: |rA-S-Q-U-E-R-O-S-O|n|cFFFFD200Zona: |rCumbre de Roca Negra Inferior" },
    [17707] = { 11325, 7, 82, nil, "Este cachorro de panda en miniatura es muy codiciado por los aventureros de todo Azeroth, a pesar de su tendencia a la narcolepsia.", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de World of Warcraft" },
    [17708] = { 11326, 5, 82, nil, "Y LOS CIELOS TEMBLARÁN, Y EL HOMBRE LLORARÁ, Y EL FIN DE LOS DÍAS... espera, ¿por qué eres tan alto?", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de World of Warcraft" },
    [17709] = { 11327, 4, 82, nil, "Un miembro pequeño y feroz del enjambre Zerg, con el zergling no se juega. Muy peligroso en grandes cantidades.", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de World of Warcraft" },
    [19772] = { 12419, 9, 2, nil, "Ingenieros de gran talento han fabricado una réplica exacta de una rana de bosque, por solo diez veces el coste de comprar una de verdad.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [23811] = { 14878, 8, 18, nil, "Se creía que la legendaria rana de cerveza estaba extinta hasta que los extraños brebajes de la Feria de la Luna Negra la sacaron de su escondite.", 6, "|cFFFFD200Evento del mundo:|r Feria de la Luna Negra" },
    [24696] = { 15186, 0, 82, nil, "Las apariciones de este querido y ultrarrecluso múrloc garantizan atraer a una multitud.", 7, "|cFFFFD200Promoción:|r BlizzCon 2005" },
    [24988] = { 15358, 0, 16466, nil, "El carácter encantador y las animadas travesuras de Lurky garantizan calmar la frustración y alegrar hasta el más sombrío de los ánimos.", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de Burning Crusade (Solo Europa)|n" },
    [25162] = { 15429, 5, 2, nil, "Advertencia: Utilice guantes y gafas al manipular el mocoso asqueroso. NO LAVAR. Manchará casi cualquier armadura.", 0, "|cFFFFD200Botín:|r Botín del mundo|n|cFFFFD200Criatura:|r Mocos y lodos" },
    [26010] = { 15699, 9, 2, nil, "Este ingenioso juguete está equipado con un interruptor secreto para desactivar su modo 'tranquilo'. Por suerte, ni los ingenieros que lo construyeron saben cómo encontrarlo.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [26045] = { 15710, 6, 2, nil, "¡Le encanta bailar, saludar y jugar contigo! Se derrite después del Festival del Invierno, pero no te preocupes; ¡volverá algún día!", 6, "|cFFFFD200Evento del mundo:|r Fiesta del Festival del Invierno|n" },
    [26529] = { 15706, 4, 2, nil, "Preferiría no pasar más tiempo dentro de una caja de regalo festiva envuelta.", 6, "|cFFFFD200Evento del mundo:|r Fiesta del Festival del Invierno" },
    [26533] = { 15698, 0, 2, nil, "Estos aliados fuera de temporada trabajan incansablemente para preparar el Festival del Invierno, y agradecerían que no se les molestara el resto del año.", 6, "|cFFFFD200Evento del mundo:|r Fiesta del Festival del Invierno" },
    [26541] = { 15705, 0, 2, nil, "Durante la majestuosa celebración del Festival del Invierno, estos fieles compañeros reparten alegría por toda la comarca. El resto del año están ocupados.", 6, "|cFFFFD200Evento del mundo:|r Fiesta del Festival del Invierno" },
    [27241] = { 16069, 0, 16466, nil, "Gurky es una artista nata, aunque sigue siendo esquiva y solo hace apariciones públicas en las ocasiones más extraordinarias.", 7, "|cFFFFD200Promoción:|r Promoción de Fansites Europeos|n" },
    [27570] = { 16085, 0, 2, nil, "El poder del amor puede ser peligroso, especialmente cuando lo empuña un goblin volador y de mal genio.", 6, "|cFFFFD200Evento del mundo:|r Amor en el aire|n|cFFFFD200Vendedor: |rMercader adorable|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\INV_ValentinesCard01:0|t|n" },
    [28505] = { 16456, 7, 16466, nil, "Este cachorro comparte muchos rasgos con sus parientes, pero juega en otra liga gracias a su talento para el canto.", 7, "|cFFFFD200Promoción:|r iCoke" },
    [28738] = { 16547, 8, 2, nil, "Lento pero seguro se gana la carrera.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [28739] = { 16548, 4, 2, nil, "Muchos asumen que 'Zampón' se refiere al movimiento del trasero de este cerdo. Descubren el verdadero significado cuando ven sus propias entrañas.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [28740] = { 16549, 4, 2, nil, "Un astuto estratega, Bigotes se hará el muerto para engañar a depredadores y cobradores de deudas.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [28871] = { 16701, 6, 2, nil, "Este pedacito de verano huele a tardes cálidas y tormentas de relámpagos. Si miras de cerca, tal vez distingas un rostro.", 6, "|cFFFFD200Evento del mundo:|r Festival del Fuego del Solsticio de Verano|n|cFFFFD200Vendedor: |rMercader del Solsticio de Verano|n|cFFFFD200Coste: |r350|TINTERFACE\\ICONS\\INV_SummerFest_FireFlower:0|t" },
    [30156] = { 17255, 2, 2, nil, "Tras una incursión de arpías en Feralas, varios nidos de hipogrifos fueron atacados. Cientos de crías quedaron huérfanas y han sido confiadas al cuidado de los druidas en la Isla Sardor.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Héroes de Azeroth" },
    [32298] = { 18381, 1, 82, nil, "Cría de los dracos abisales de Terrallende, este joven dragón aún está asumiendo su papel como cazador, protector y adorable terror de los cielos.", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de Burning Crusade" },
    [33050] = { 18839, 8, 2, nil, "Solo los deseos mágicos crean cangrejos mágicos. Si deseas un pez, pesca un deseo.", 3, "|cFFFFD200Pesca:|r Pesca (430)|n|cFFFFD200Zona:|r Bosque de Terokkar (Bancos de pesca)" },
    [35156] = { 20408, 5, 2, nil, "El etéreo Rashaad comenzó a criar a estas enigmáticas criaturas tras descubrir su capacidad para alimentarse de energías arcanas.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35239] = { 20472, 4, 2, nil, "Este conejito es lo más adorable que su adversario jamás verá. También será lo último.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35907] = { 21010, 2, 2, nil, "Delicado habitante de la Isla Bruma Azur, se rumorea que este insecto mágico posee habilidades curativas.", 2, "|cFFFFD200Vendedor: |rSixx|n|cFFFFD200Zona: |rEl Exodar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [35909] = { 21009, 2, 2, nil, "Fruto de la exposición a energías mágicas salvajes, este insecto es el inesperadamente colorido resultado de liberar especies de polillas de Azeroth en los ecodomos de Tormenta Abisal.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [35910] = { 21008, 2, 2, nil, "Prefiere volar durante tormentas eléctricas, que son comunes en la Isla Bruma Azur.", 2, "|cFFFFD200Vendedor: |rSixx|n|cFFFFD200Zona: |rEl Exodar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [35911] = { 21018, 2, 2, nil, "Prefiere volar durante noches de niebla, que son comunes en la Isla Bruma Azur.", 2, "|cFFFFD200Vendedor: |rSixx|n|cFFFFD200Zona: |rEl Exodar|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36027] = { 21055, 1, 2, nil, "Muy apreciada en el pasado por los criadores de dracohalcones de Lunargenta. Llama la atención de los depredadores por la noche, por lo que debe desarrollar sus sentidos a temprana edad.", 2, "|cFFFFD200Vendedor: |rJilanne|n|cFFFFD200Zona: |rBosque Canción Eterna|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36028] = { 21064, 1, 2, nil, "Enemigo mortal de los dracohalcones plateados; en muy buenos términos con los dracohalcones dorados.", 2, "|cFFFFD200Vendedor: |rJilanne|n|cFFFFD200Zona: |rBosque Canción Eterna|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36029] = { 21063, 1, 2, nil, "Especie feroz de dracohalcón, a menudo vista lanzándose en picado sobre sus presas desde lo alto del cielo.", 2, "|cFFFFD200Vendedor: |rJilanne|n|cFFFFD200Zona: |rBosque Canción Eterna|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-SILVERICON.BLP:0|t" },
    [36031] = { 21056, 1, 2, nil, "Criada por los pocos tratantes que aún están dispuestos a comerciar en Tormenta Abisal.", 2, "|cFFFFD200Vendedor: |rTratante Rashaad|n|cFFFFD200Zona: |rTormenta Abisal|n|cFFFFD200Coste: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [36034] = { 21076, 2, 2, nil, "Utilizado comúnmente por los esporinos como fuente de luz mientras navegan por los canales de Marisma de Zangar, este insecto luminiscente les ayuda a evitar a los peligrosos aguijoneros del pantano.", 0, "|cFFFFD200Botín: |rAguijonero del pantano|n|cFFFFD200Zona: |rMarisma de Zangar" },
    [39181] = { 22445, 2, 18, nil, "Las energías mágicas liberadas durante la transformación de Alaceleste de vuelta a su verdadera forma arakkoa liberaron a esta pobre criatura, un polluelo encarcelado por Luanga para alimentar su vil maldición.", 1, "|cFFFFD200Misión:|r Alaceleste|n|cFFFFD200Zona:|r Bosque de Terokkar|n|n" },
    [39709] = { 22943, 4, 2, nil, "Más de un juerguista ebrio de la Fiesta de la Cerveza ha contado la historia de esta misteriosa criatura, pero pocos recuerdan el relato a la mañana siguiente.", 6, "|cFFFFD200Evento del mundo:|r Fiesta de la Cerveza" },
    [40405] = { 23198, 4, 16466, nil, "Lucky chilla cuando está enfadado o cuando está comiendo. En cualquier caso, no querrás molestarlo.", 7, "|cFFFFD200Promoción:|r World Wide Invitational 2007|n" },
    [40549] = { 23234, 7, 2, nil, "Aunque reacio a desprenderse de Plátanos, Landro se dio cuenta de que sería más seguro si la mascota estuviera lejos de Bahía del Botín cuando su padre, el Rey Mukla, descubriera su desaparición.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r A través del Portal Oscuro" },
    [40613] = { 23231, 5, 2, nil, "Es ligeramente malvado pero sumamente narcoléptico. ¡Mantenlo alejado de las alimañas!", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [40614] = { 23258, 4, 2, nil, "Los sin'dorei usan halcones zancudos como monturas, pero este pequeño fue considerado no apto tras ser diagnosticado con numerosos trastornos de ansiedad.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [40634] = { 23266, 4, 2, nil, "Los elekk domesticados son entrenados como monturas por el pueblo draenei. En estado salvaje son cazados por sus colmillos de marfil.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [40990] = { 23274, 4, 82, nil, "Apestoso usa su aroma para repeler depredadores y atraer gatos. Tiene mucho más éxito con lo primero que con lo segundo.", 5, "|cFFFFD200Logro: |rCompra bien, compra mascotas... ¡con cabeza!|n|cFFFFD200Categoría: |rGeneral" },
    [42609] = { 23909, 6, 2, nil, "A esta traviesa calabaza le gusta brotar del suelo y darte un susto de muerte. ¡Viva la fiesta de Halloween!", 6, "|cFFFFD200Evento del mundo:|r Halloween" },
    [43697] = { 24388, 8, 2, nil, "La piel y la carne del crocolisco son muy apreciadas por los cazadores, pero la bestia es feroz y rara vez se la toma por sorpresa.", 3, "|cFFFFD200Profesión: |rPesca|n|cFFFFD200Zona: |rShattrath" },
    [43698] = { 24389, 8, 2, nil, "Alientomoco es como los demás crocoliscos, excepto por su excelente sentido del humor.", 3, "|cFFFFD200Profesión:|r Pesca|n|cFFFFD200Zona:|r Shattrath" },
    [43918] = { 24480, 8, 2, nil, "Los médicos brujos Amani han convertido a muchas víctimas en ranas. Algunas nunca se recuperan.", 0, "|cFFFFD200Botín:|r Rana de bosque|n|cFFFFD200Zona:|r Zul'Aman" },
    [44369] = { 24753, 4, 2, nil, "Una criatura tímida, el elekk rosa solo se dejará ver ante quienes se hayan ganado su amistad, o ante cualquiera que esté demasiado ebrio como para hacerle daño.", 6, "|cFFFFD200Evento del mundo:|r Fiesta de la Cerveza|n|cFFFFD200Vendedor: |rBelbi Cortaprecio|n|cFFFFD200Zona: |rDun Morogh|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\INV_Misc_Coin_01:0|t|n|n|cFFFFD200Vendedor: |rBliz Llavededo|n|cFFFFD200Zona: |rDurotar|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\INV_Misc_Coin_01:0|t" },
    [45082] = { 25062, 2, 2, nil, "Los murciélagos de esporas salvajes son criaturas feroces, pero si se domestican a temprana edad, pueden ser compañeros leales.", 2, "|cFFFFD200Vendedor: |rMycah|n|cFFFFD200Zona: |rMarisma de Zangar|n|cFFFFD200Facción: |rEsporaggar - Exaltado|n|cFFFFD200Coste: |r30|TINTERFACE\\ICONS\\INV_Mushroom_02:0|t" },
    [45125] = { 25109, 9, 2, nil, "Cuando la Legión Ardiente invadió Terrallende, Landro Tirofeliz aportó este diseño al esfuerzo de guerra. Tanto la Alianza como la Horda descartaron su producción.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Marcha de la Legión" },
    [45127] = { 25110, 2, 2050, nil, "Mucho más silencioso que un dragón de verdad.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Marcha de la Legión" },
    [45174] = { 25146, 4, 82, nil, "Este cerdo dorado honra a sus antepasados trayendo buena fortuna a sus aliados.", 7, "|cFFFFD200Promoción:|r Recluta a un amigo|n" },
    [45175] = { 25147, 4, 82, nil, "Los druidas piensan que los cerdos plateados tienen un vínculo especial con los cerdos dorados, ya que ambas razas aparecieron en Azeroth al mismo tiempo.", 7, "|cFFFFD200Promoción:|r Recluta a un amigo" },
    [45890] = { 25706, 6, 2, nil, "Los chamanes ancianos han advertido que fuegos fatuos de Ragnaros, leales sirvientes del Señor del Fuego, han llegado al Frente de Fuego. Se aconseja precaución.", 11, "" },
    [46425] = { 26050, 8, 2, nil, "Los crocoliscos son depredadores anfibios de seis patas que habitan aguas costeras. Los arqueólogos creen que podrían descender de los diemetradones del Cráter de Un'Goro.", 3, "|cFFFFD200Profesión: |rPesca|n|cFFFFD200Zona: |rShattrath" },
    [46426] = { 26056, 8, 2, nil, "Tras estudiar la especie de los crocoliscos durante varios años, el famoso pescador Nat Pagle determinó que las crías de crocolisco son casi inofensivas.", 3, "|cFFFFD200Profesión: |rPesca|n|cFFFFD200Zona: |rShattrath" },
    [46599] = { 26119, 6, 2, nil, "Hijo del dios fénix Al'ar, el polluelo echa a volar inmediatamente tras su nacimiento.", 0, "|cFFFFD200Botín: |rKael'thas Caminante del Sol|n|cFFFFD200Zona: |rBancal del Magister" },
    [48406] = { 27217, 1, 16402, nil, "Estas deslumbrantes criaturas, otorgadas a los héroes por su victoria en batalla, representan valentía y fuerza.", 7, "|cFFFFD200Promoción:|r Evento de Campos de Batalla" },
    [48408] = { 27346, 1, 16402, nil, "Solo a los héroes que han demostrado su valor mediante grandes hazañas se les obsequia con una de estas místicas criaturas serpentinas.", 7, "|cFFFFD200Promoción:|r Evento JcJ de China" },
    [49964] = { 27914, 5, 2, nil, "Los tratantes de almas etéreos viajarán con aquellos capaces de liberar las esencias que necesitan de anfitriones rebeldes.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r La Caza de Illidan" },
    [51716] = { 28470, 2, 2, nil, "Nativas del Bosque de Terokkar, las rayas abisales desovan durante la temporada de lluvias. De los cientos de crías que nacen de una puesta, muy pocas sobreviven hasta la edad adulta.", 2, "|cFFFFD200Vendedor: |rGrella|n|cFFFFD200Zona: |rBosque de Terokkar|n|cFFFFD200Facción: |rGuardia del cielo Sha'tari - Exaltado|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [51851] = { 28513, 3, 16402, nil, "Los murciélagos vampiro han sido entrenados como exploradores y monturas por los Renegados de Entrañas y los trolls Amani de Zul'Aman.", 0, "|cFFFFD200Botín: |rPríncipe Tenris Sangrepenumbra|n|cFFFFD200Zona: |rKarazhan" },
    [52615] = { 28883, 3, 82, nil, "Creado por accidente cuando los poderes mortíferos del Rey Exánime alzaron a Dientefrio de la no-muerte.", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de Wrath of the Lich King" },
    [53082] = { 29089, 0, 16466, nil, "'¡Yo soy la Justicia misma!'", 7, "|cFFFFD200Promoción:|r World Wide Invitational 2008" },
    [53316] = { 29147, 3, 2, nil, "Cuando percibe la muerte inminente de una criatura cercana, la calavera emite una carcajada ensordecedora.", 2, "|cFFFFD200Vendedor: |rDarahir|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r40|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [54187] = { 24968, 9, 2, nil, "Este guerrero mecánico es un regalo favorito durante el Festival del Invierno. Pilas no incluidas, ¡pero los cohetes sí!", 6, "|cFFFFD200Evento del mundo:|r Fiesta del Festival del Invierno" },
    [55068] = { 29726, 8, 16466, nil, "El aspecto del Sr. Frío evoca una era más civilizada, cuando los duelistas luchaban en esmoquin.", 7, "|cFFFFD200Promoción:|r Fusión de cuentas de WoW/Blizzard" },
    [59250] = { 31575, 4, 2, nil, "No te gustaría encontrarte con esta rata en un callejón oscuro. Ni en ningún otro sitio, la verdad.", 3, "|cFFFFD200Profesión:|r Pesca|n|cFFFFD200Zona:|r Dalaran" },
    [61348] = { 32589, 2, 2, nil, "A diferencia de la mayoría de los 'huevos misteriosos' del gorloc Geen, este realmente contenía algo con vida.", 0, "|cFFFFD200Botín: |rHuevo misterioso" },
    [61349] = { 32590, 2, 2, nil, "El raro picabueyes albino es venerado entre Los Oráculos. Se considera un augurio de fuertes tormentas, buenas cosechas de larvas y wolvar en hibernación.", 0, "|cFFFFD200Botín: |rHuevo misterioso" },
    [61350] = { 32592, 1, 2, nil, "Estas voraces crías crecen a un ritmo increíble y pueden devorar casi el doble de su peso en carne cruda al día.", 0, "|cFFFFD200Botín: |rHuevo misterioso" },
    [61351] = { 32591, 7, 2, nil, "Las cobras de Azeroth son famosas por su veneno de acción rápida y sus ataques certeros.", 0, "|cFFFFD200Botín: |rHuevo misterioso" },
    [61357] = { 32595, 8, 2, nil, "Destaca por sus grandes ojos y su andar descarado.", 2, "|cFFFFD200Vendedor: |rSairuk|n|cFFFFD200Zona: |rCementerio de Dragones|n|cFFFFD200Facción: |rLos Kalu'ak - Exaltado|n|cFFFFD200Coste: |r12|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t|n|n|cFFFFD200Vendedor: |rTanaika|n|cFFFFD200Zona: |rFiordo Aquilonal|n|cFFFFD200Facción: |rLos Kalu'ak - Exaltado|n|cFFFFD200Coste: |r12|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61472] = { 32643, 6, 82, nil, "Para evitar que los aprendices usaran en secreto al familiar para hacer sus tareas, los archimagos repartieron el ritual para invocar a la criatura por las páginas de varios libros de hechizos ocultos por Dalaran.", 5, "|cFFFFD200Logro:|r Conocimiento superior|n|cFFFFD200Categoría: |rGeneral" },
    [61725] = { 32791, 4, 2, nil, "Los conejos de primavera simbolizan la fertilidad, y les encanta demostrar por qué.", 6, "|cFFFFD200Evento del mundo:|r El Jardín Noble|n|cFFFFD200Vendedor: |rMercader del Jardín Noble|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Achievement_Noblegarden_Chocolate_Egg:0|t" },
    [61773] = { 32818, 2, 82, nil, "Es humilde, clarividente y delicioso con salsa de arándanos.", 6, "|cFFFFD200Evento del mundo:|r Generosidad del Peregrino" },
    [61855] = { 32841, 7, 16466, nil, "Este raro oso se cría por su pequeño tamaño y su apariencia perpetuamente juvenil.", 5, "|cFFFFD200Logro: |r4.º aniversario de WoW|n|cFFFFD200Categoría: |rProezas de fuerza" },
    [61991] = { 32939, 4, 82, nil, "Le gusta la compañía de amigos. Setenta y cinco de ellos, para ser precisos.", 5, "|cFFFFD200Logro: |rGran cazador de fieras|n|cFFFFD200Categoría: |rGeneral" },
    [62491] = { 33188, 6, 2, nil, "Siempre se despierta bailando. ¡Qué arbolito más feliz!", 2, "|cFFFFD200Vendedor: |rRook Puñohalcón|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [62508] = { 33194, 7, 2, nil, "Los osos de Dun Morogh son apreciados por su resistencia, lealtad y destreza en combate. Su tiempo entre los enanos no hace mucho por mitigar su ferocidad.", 2, "|cFFFFD200Vendedor: |rDerrick Barbanevada|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t " },
    [62510] = { 33197, 2, 2, nil, "Puede detectar el latido del corazón de un oponente mediante ecolocalización.", 2, "|cFFFFD200Vendedor: |rEliza Killian|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [62513] = { 33198, 7, 2, nil, "El volátil escorpión de Durotar es un feroz depredador del desierto. Es famoso por picar a su dueño solo de vez en cuando.", 2, "|cFFFFD200Vendedor: |rFreka Hachasangre|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t " },
    [62516] = { 33200, 4, 2, nil, "A diferencia de la variedad polimorfada, las ovejas de pura raza pueden ser bastante aterradoras.", 2, "|cFFFFD200Vendedor: |rCabo Arthur Flew|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t " },
    [62542] = { 33219, 4, 2, nil, "La velocidad de un zancudo en campo abierto no tiene rival, por lo que los depredadores dependen del sigilo y las tácticas de manada al cazarlos.", 2, "|cFFFFD200Vendedor: |rDoru Cuernotrueno|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t " },
    [62561] = { 33226, 8, 2, nil, "El reptador de las costas se ha adaptado al frío norteño hibernando bajo las playas de las islas.", 3, "|cFFFFD200Profesión: |rPesca|n|cFFFFD200Zona: |rDalaran" },
    [62562] = { 33205, 6, 2, nil, "Los efectos a largo plazo de la contaminación causada por El Exodar aún están bajo observación.", 2, "|cFFFFD200Vendedor: |rIrisee|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t |n" },
    [62564] = { 33227, 5, 2, nil, "Creada por un aprendiz elfo de sangre, esta escoba sería sumamente útil si alguien pudiera averiguar cómo hacer que se detenga.", 2, "|cFFFFD200Vendedor: |rTrellis Solmatutino|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t " },
    [62609] = { 33238, 0, 659, nil, "Muchos de los jóvenes de Ventormenta se unieron a la Cruzada Argenta como escuderos, con la esperanza de servir algún día a la Luz Sagrada en la batalla.", 1, "|cFFFFD200Misión:|r Se alza un campeón|n|cFFFFD200Zona:|r Corona de Hielo" },
    [62674] = { 33274, 9, 2, nil, "Utilizado como montura de entrenamiento para jóvenes gnomos, el mecanopollo carece de la velocidad pero tiene todo el encanto de sus hermanos mayores.", 2, "|cFFFFD200Vendedor: |rRillie Ejeplata|n|cFFFFD200Zona: |rCorona de Hielo" },
    [62746] = { 33239, 0, 403, nil, "Estos jóvenes orcos se esfuerzan por encarnar las virtudes de la Cruzada Argenta: valor, fuerza e integridad.", 1, "|cFFFFD200Misión:|r Se alza un campeón|n|cFFFFD200Zona:|r Corona de Hielo" },
    [63318] = { 33578, 0, 16466, nil, "Murkimus es el más temible de todos los guerreros de arena múrloc. Y durante un tiempo, el único.", 7, "|cFFFFD200Promoción:|r Torneo de Arenas" },
    [63712] = { 33810, 3, 2050, nil, "En realidad son tres mascotas en una. ¡No sabrás cuál te tocará hasta que la invoques!", 2, "|cFFFFD200Vendedor: |rSamamba|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|n" },
    [65358] = { 34364, 7, 2, nil, "Muchos se han burlado de este gato antes de la batalla. Sus últimas palabras suelen ser: 'Ven aquí, gatito'.", 2, "|cFFFFD200Vendedor: |rBreanni|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [65381] = { 33530, 0, 18, nil, "El saltarín gorloc es un primo lejano del múrloc.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [65382] = { 33529, 0, 18, nil, "A pesar de su menor estatura, los wolvar son algunas de las criaturas más agresivas de Rasganorte. Esto a menudo hace que su curiosidad resulte intimidante.", 6, "|cFFFFD200Evento del mundo:|r Semana de los Niños" },
    [65682] = { 34587, 9, 16466, nil, "Un robot de combate alimentado por deliciosos electrolitos rojos o azules.", 7, "|cFFFFD200Promoción:|r Promoción de Mountain Dew" },
    [66030] = { 34694, 0, 82, nil, "Solo los múrlocs más extraordinarios logran cruzar barreras dimensionales con éxito. Menos aún regresan con el tipo de armadura y armamento avanzado que posee Grunty.", 7, "|cFFFFD200Promoción:|r BlizzCon 2009" },
    [66096] = { 34724, 5, 2, nil, "Esta especie sumamente rara de vermis de maná es apreciada por su coloración única y su temperamento uniforme.", 2, "|cFFFFD200Vendedor: |rHiren Cantosolemnis|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Facción: |rEl Pacto de Plata - Exaltado|n|cFFFFD200Coste: |r40|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|n" },
    [66520] = { 34930, 5, 82, nil, "Considerados portadores de buena suerte, los tigres tallados en jade son muy codiciados, pero domar a un tigre de jade auténtico es una recompensa aún mayor.", 7, "|cFFFFD200Promoción:|r Recluta a un amigo" },
    [67413] = { 35396, 7, 2, nil, "Rara vez abandona el nido hasta la madurez. Disfruta gastando bromas al nido de Tajobuche cercano.", 0, "|cFFFFD200Botín: |rNido de Dardo|n|cFFFFD200Zona: |rMarjal Revolcafango" },
    [67414] = { 35395, 7, 2, nil, "La demanda de esta raza de piel púrpura ha reducido drásticamente la población de raptores cerca de las Cuevas de los Lamentos.", 0, "|cFFFFD200Botín: |rGuardián Desviado, Devastador Desviado|n|cFFFFD200Zona: |rLas Cuevas de los Lamentos" },
    [67415] = { 35400, 7, 2, nil, "Este astuto raptor nació en los páramos helados de Rasganorte. Su dura crianza le otorga fortaleza donde muchos otros perecerían.", 0, "|cFFFFD200Botín: |rRaptor de Gundrak|n|cFFFFD200Zona: |rZul'Drak" },
    [67416] = { 35387, 7, 2, nil, "Esta cría de Takk el Saltarín es increíblemente ágil y puede maniobrar en entornos difíciles con facilidad.", 0, "|cFFFFD200Botín: |rNido de Takk|n|cFFFFD200Zona: |rLos Baldíos" },
    [67417] = { 35399, 7, 2, nil, "Esta cría es codiciada por su coloración única. A pesar del cariñoso cuidado de Breanni, la naturaleza salvaje del raptor no se puede contener.", 2, "|cFFFFD200Vendedor: |rBreanni|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [67418] = { 35397, 7, 2, nil, "Más grandes que otros infantes de raptor, estas crías se convierten en imponentes bestias reptilianas capaces de una devastación masiva.", 0, "|cFFFFD200Botín: |rNido de matriarca ravasaurio|n|cFFFFD200Zona: |rCráter de Un'Goro" },
    [67419] = { 35398, 7, 2, nil, "Los huevos de Tajobuche son protegidos ferozmente por sus madres. Su ternura oculta su ferocidad heredada.", 0, "|cFFFFD200Botín: |rNido de matriarca Tajobuche|n|cFFFFD200Zona: |rLos Humedales" },
    [67420] = { 35394, 7, 2, nil, "Los raptores Razzashi están entre los depredadores más inteligentes de la jungla, lo que los convierte en los favoritos de los trolls Gurubashi.", 0, "|cFFFFD200Botín: |rBotín del mundo|n|cFFFFD200Zona: |rVega de Tuercespina" },
    [67527] = { 35468, 5, 16466, nil, "La pantera de ónice es invisible por la noche, como una sombra al acecho, y desaparece con el amanecer.", 7, "|cFFFFD200Promoción:|r Evento de Corea" },
    [68767] = { 36482, 2, 2, nil, "Ver estas cometas surcando las costas de Rasganorte es una clara señal de que hay colmillarr cerca.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Guerra de la Plaga" },
    [68810] = { 36511, 5, 2, nil, "Cariñosos y curiosos, estos gatitos parecen encontrar los escondites más peculiares.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Guerra de la Plaga" },
    [69002] = { 36607, 1, 16466, nil, "Engendro de Onyxia, este joven dragón ha decidido que no quiere seguir los pasos catastróficos de sus abuelos.", 5, "|cFFFFD200Logro: |r5.º aniversario de WoW|n|cFFFFD200Categoría: |rProezas de fuerza" },
    [69452] = { 36871, 6, 82, nil, "Presentes en las Tierras del Fuego y el Núcleo de Magma, los canes del Núcleo pueden rastrear su linaje hasta el macho alfa, Magmadar.", 7, "|cFFFFD200Promoción:|r Vinculación con Authenticator|n" },
    [69535] = { 36908, 2, 82, nil, "Un regalo de los enanos Martillo Salvaje a los héroes de la Alianza, estas crías son descendientes de los mismos grifos que Falstad y su séquito montaron hacia Grim Batol.", 9, "|cFFFFD200Tienda del juego|r" },
    [69536] = { 36909, 7, 82, nil, "Thorg Sin Piernas nunca prestó atención al viejo dicho orco: 'No le tires de la cola a un dracoleón'.", 9, "|cFFFFD200Tienda del juego|r" },
    [69539] = { 36910, 5, 82, nil, "Una familia de tigres rara vez vista; muchos creen (quizá erróneamente) que alguna magia residual u otro evento es responsable de su color único.", 7, "|cFFFFD200Promoción:|r Recluta a un amigo" },
    [69541] = { 36911, 0, 82, nil, "El monje pandaren es un intrépido compañero de viaje, que entrena constantemente en su arte... a menos que le ofrezcas un trago. Considera de mala educación rechazarlo.", 9, "|cFFFFD200Tienda del juego|r" },
    [69677] = { 36979, 3, 82, nil, "En vida, Kel'Thuzad traicionó al Kirin Tor y creó el Culto de los Malditos. En la muerte, sirve a la Plaga como el Señor Archiliche de Naxxramas.", 9, "|cFFFFD200Tienda del juego|r" },
    [70613] = { 37865, 4, 82, nil, "Aunque pequeños, los carlinos son muy peligrosos cuando se les provoca.", 5, "|cFFFFD200Logro: |rEn busca de multitudes|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [71840] = { 38374, 5, 2, nil, "A este, ejem, 'adorable' pequeñín le gusta jugar con las alimañas. Tan solo no dejes que se acerquen demasiado.", 6, "|cFFFFD200Evento del mundo:|r Amor en el aire" },
    [74932] = { 40198, 6, 2, nil, "Aunque no es tan destructivo como su amo original, Ahune el Señor de la Escarcha, el vermis gélido es conocido por lanzar bolas de nieve heladas a aventureros desprevenidos.", 6, "|cFFFFD200Evento del mundo:|r Festival del Fuego del Solsticio de Verano" },
    [75134] = { 40295, 9, 2, nil, "El juguete más vendido de Jepetto esta temporada; el nuevo chasis azul del robot tiene a los niños de todo Azeroth disputándose este peleón robot de batalla.", 2, "|cFFFFD200Vendedor: |rVendedores del mundo|n|cFFFFD200Coste: |r50|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [75613] = { 40624, 1, 82, nil, "Breanni en Dalaran, una de las coleccionistas de mascotas exóticas más destacadas del mundo, solo otorgará el místico Dragón celestial a colegas coleccionistas cuya obsesión rivalice con la suya.", 5, "|cFFFFD200Logro: |rLa tienda de mascotas más pequeña|n|cFFFFD200Categoría: |rDuelos de mascotas" },
    [75906] = { 40703, 9, 82, nil, "Inspirado en el enorme prototipo de los titanes de Ulduar, este pequeño y volátil ensamblaje no se anda con chiquitas cuando juega.", 9, "|cFFFFD200Tienda del juego|r" },
    [75936] = { 40721, 0, 34, nil, "Murkimus es el más temible de todos los guerreros de arena múrloc. Y el único.", 11, "" },
    [78381] = { 42078, 9, 82, nil, "Poderosa artillería del ejército Terran. ¡El Thor siempre es el primero en entrar y el último en salir!", 7, "|cFFFFD200Promoción:|r Edición de Coleccionista de StarCraft II: Wings of Liberty" },
    [23531] = { 14755, 1, 16466, nil, "Las leyendas cuentan que estos vibrantes seres esmeralda traen buena fortuna y viajes seguros a sus dueños.", 7, "|cFFFFD200Promoción:|r iCoke China" },
    [23530] = { 14756, 1, 16466, nil, "Se dice que trae buena fortuna cuando se le avista en otoño. Conocido por esconderse de criaturas desconocidas.", 7, "|cFFFFD200Promoción:|r iCoke China" },
    [28487] = { 16445, 0, 82, nil, "Terky es tan tímida como adorable, y prefiere la compañía de amigos cercanos a la de desconocidos.", 0, "|cFFFFD200Botín:|r Huevo de múrloc blanco" },
    [25018] = { 15361, 0, 16466, nil, "Murki es una de las especies de múrloc más raras del mundo.", 7, "|cFFFFD200Promoción:|r Evento Promocional de Corea" },
    [66175] = { 34770, 3, 2, nil, "A estos títeres poseídos se les otorga una apariencia de vida gracias a los espíritus caprichosos de los difuntos.", 6, "|cFFFFD200Evento del mundo:|r Festividad de los Muertos" },
    [10699] = { 7546, 1, 2, nil, "La cría bronce estuvo perdida en el tiempo hasta que un evento inusual le permitió escapar.", 0, "|cFFFFD200Botín: |rHorda de Hierro|n|cFFFFD200Zona: |rTierras Devastadas" },
    [30152] = { 17254, 7, 66, nil, "Uno de los cachorros de Ash'alah, confiado a ti por los Tejedores de Sueños.", 2, "|cFFFFD200Vendedor: |rSylvia Espinaprima|n|cFFFFD200Zona: |rVal'sharah|n|cFFFFD200Facción: |rTejedores de Sueños - Venerado|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },

